def normalize_us_phone(text: str) -> str:
    digits = "".join(filter(str.isdigit, text))
    if len(digits) != 10:
        raise ValueError("Input must contain exactly 10 digits.")
    return f"{digits[0:3]}-{digits[3:6]}-{digits[6:10]}"

