        if v not in in_degree:
            in_degree[v] = 0

    for node in nodes:
        if node not in in_degree:
            in_degree[node] = 0

    for u, v in edges:
        in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    topological_order = []

    while queue:
        u = queue.pop

