def topo_sort_nodes(nodes: list[str], edges: list[tuple[str, str]]) -> list[str]:
    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for u, v in edges:
        if u not in adj or v not in adj:
            raise ValueError("Edge contains node not in the provided node list.")
        adj[u].append(v)
        in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    sorted_nodes = []

    while queue:
        u = queue.pop(0)
        sorted_nodes.append(u)

        for v in adj[u]:
